CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, alias VARCHAR(80) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at DATETIME NOT NULL DEFAULT UTC_TIMESTAMP());
CREATE TABLE IF NOT EXISTS lunch_plans (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,date DATE NOT NULL,mensa_id VARCHAR(32) NOT NULL,slot_id VARCHAR(5) NOT NULL,meeting_point_id VARCHAR(64) NULL,visibility VARCHAR(10) NOT NULL DEFAULT 'private',reminder BOOLEAN NOT NULL DEFAULT 0,status VARCHAR(12) NOT NULL DEFAULT 'confirmed',version INT NOT NULL DEFAULT 1,starts_at DATETIME NOT NULL,ends_at DATETIME NOT NULL,UNIQUE KEY user_date(user_id,date),KEY aggregate_plan(date,mensa_id,slot_id,status),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS friendships (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_low BIGINT UNSIGNED NOT NULL,user_high BIGINT UNSIGNED NOT NULL,initiator_id BIGINT UNSIGNED NOT NULL,status VARCHAR(12) NOT NULL DEFAULT 'requested',UNIQUE KEY pair_unique(user_low,user_high),FOREIGN KEY(user_low) REFERENCES users(id),FOREIGN KEY(user_high) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS friend_invites (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME NOT NULL,revoked BOOLEAN NOT NULL DEFAULT 0,used_by BIGINT UNSIGNED NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS mutation_requests (user_id BIGINT UNSIGNED NOT NULL,request_id VARCHAR(80) NOT NULL,response_json LONGTEXT NOT NULL,PRIMARY KEY(user_id,request_id));
CREATE TABLE IF NOT EXISTS rate_limits (bucket CHAR(64) NOT NULL PRIMARY KEY,attempts INT NOT NULL DEFAULT 0,window_at DATETIME NOT NULL);
